// Purpose: Open Configured Cycle Window. Keep this deterministic and fail closed.
const now = new Date();
const cycleDay = 3, deadlineDays = 5;
const day = now.getDate();
if (day < cycleDay || day > cycleDay + deadlineDays)
    return [];
const upper = now.toISOString();
const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, cycleDay));
return [{ json: { run_id: `WIO_CREDIT:${upper}`, source_code: 'WIO_CREDIT', window_start: start.toISOString(), run_upper_bound: upper, cycle_day: cycleDay, deadline_at: new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), cycleDay + deadlineDays, 23, 59, 59)).toISOString(), period_key: `${now.getUTCFullYear()}-${String(now.getUTCMonth() + 1).padStart(2, '0')}`, trigger_kind: 'SCHEDULE' } }];
